package edu.pbs.hub.controller; import edu.pbs.hub.model.Notice;import edu.pbs.hub.repo.NoticeRepository;import edu.pbs.hub.config.AdminGuard;import org.springframework.web.bind.annotation.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;
@RestController @RequestMapping("/api/notices") public class NoticeController{private final NoticeRepository repo;private final AdminGuard guard;public NoticeController(NoticeRepository r,AdminGuard g){repo=r;guard=g;}@GetMapping public List<Notice> list(){return repo.findByActiveTrueOrderByCreatedAtDesc();}@PostMapping public Notice add(@RequestBody Notice n,HttpServletRequest q){guard.check(q);return repo.save(n);}@PutMapping("/{id}") public Notice edit(@PathVariable Long id,@RequestBody Notice n,HttpServletRequest q){guard.check(q);Notice o=repo.findById(id).orElseThrow();o.setTitle(n.getTitle());o.setMessage(n.getMessage());o.setTag(n.getTag());o.setActive(n.isActive());return repo.save(o);}@DeleteMapping("/{id}")public void delete(@PathVariable Long id,HttpServletRequest q){guard.check(q);repo.deleteById(id);}}
